"""Migration of the Meridian CRM 4.2 nightly credit-hold sweep."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


_CENTS = Decimal("0.01")


def _money(value: object) -> Decimal:
    """Apply legacy NVL numeric coercion and stored-money cent rounding."""
    if value is None or value == "":
        return Decimal("0")

    try:
        return Decimal(str(value)).quantize(_CENTS, rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError):
        return Decimal("0")


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """Apply the legacy credit-hold sweep without mutating input rows."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, object]] = []

    # CRMScript FOR EACH uses ascending primary-key order, independently of
    # the order in which rows were supplied to this function.
    indexed_accounts = sorted(
        enumerate(new_accounts),
        key=lambda item: item[1].get("ACCT_ID", ""),
    )

    for _, account in indexed_accounts:
        if account.get("DEL_FLG") == "Y" or account.get("ACCT_TYP") != "C":
            continue

        acct_id = account.get("ACCT_ID")
        exposure = Decimal("0")

        # The legacy inner FOR EACH considers only live matching orders.
        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _money(order.get("TOT_AMT"))

        credit_limit = _money(account.get("CRED_LIMIT"))

        # Preserve the script's sequential IF evaluation: the second IF sees
        # any CRED_HOLD change made by the first IF.
        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * Decimal(8) / Decimal(10) and account.get(
            "CRED_HOLD"
        ) == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
